import { test, expect } from 'bun:test';
import { formatFlightDate } from '../src/flight-date.js';
test('preserves a date-only departure label', () => {
  expect(formatFlightDate('2026-09-14')).toBe('Sep 14, 2026');
});
test('preserves year and leap-day boundaries', () => {
  expect(formatFlightDate('2026-01-01')).toBe('Jan 1, 2026');
  expect(formatFlightDate('2024-02-29')).toBe('Feb 29, 2024');
});
